import { useEffect, useState } from "react";
import axios from "axios";

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [quiz, setQuiz] = useState("");

  useEffect(() => {
    axios
      .get("/api/students/1/enrollments")
      .then((res) => setCourses(res.data))
      .catch((err) => console.log(err));
  }, []);

  const generateQuiz = async (topic) => {
    try {
      const res = await axios.get(`/api/quiz/generate/${topic}`);
      setQuiz(res.data.quiz);
    } catch (err) {
      console.log(err);
      setQuiz("Failed to generate quiz");
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-xl mb-4 font-bold">My Courses</h1>

      {/* Courses List */}
      {courses.length === 0 ? (
        <p>No courses found</p>
      ) : (
        courses.map((course) => (
          <div key={course.course_id} className="p-4 border mb-3 rounded">
            <h2 className="font-semibold">{course.course_name}</h2>
            <p>Progress: {course.progress || 0}%</p>
          </div>
        ))
      )}

      {/* Quiz Button */}
      <button
        onClick={() => generateQuiz("DBMS")}
        className="bg-green-500 text-white px-4 py-2 rounded mt-4"
      >
        Generate AI Quiz
      </button>

      {/* Quiz Display */}
      {quiz && (
        <pre className="mt-4 bg-white p-4 border whitespace-pre-wrap">
          {quiz}
        </pre>
      )}
    </div>
  );
}
